cdc_stream = [
    {'op': 'c', 'after': {'id': 1, 'nombre': 'Tablet', 'precio': 200.0}},
    {'op': 'c', 'after': {'id': 2, 'nombre': 'Teclado', 'precio': 50.0}},
    {'op': 'u', 'before': {'precio': 200.0}, 'after': {'id': 1, 'nombre': 'Tablet Pro', 'precio': 250.0}},
    {'op': 'd', 'before': {'id': 2}},
]

table_state = {}
for ev in cdc_stream:
    op = ev['op']
    if op in ('c', 'u'):
        table_state[ev['after']['id']] = ev['after']
    elif op == 'd':
        table_state.pop(ev['before']['id'], None)

print('=== ESTADO FINAL TRAS RECONCILIACIÓN CDC ===')
for row_id, data in sorted(table_state.items()):
    print(f'ID {row_id}: {data}')
